import app from 'flarum/admin/app';

/**
 * `visible` and `tree` are read by core's admin search (GeneralSearchSource). The search calls
 * `visible()` without arguments, so it sees saved values; SentrySettingsPage passes its live,
 * unsaved values so dependent settings appear as soon as their parent is changed.
 */

export const savedValue = key => app.data.settings[key];
export const performanceMonitoringEnabled = function (value) {
  if (value === void 0) {
    value = savedValue;
  }
  return (Number(value('fof-sentry.monitor_performance')) || 0) > 0;
};
export const nPlusOneDetectionEnabled = function (value) {
  if (value === void 0) {
    value = savedValue;
  }
  return performanceMonitoringEnabled(value) && value('fof-sentry.db.n_plus_one_detection') === '1';
};
export const javascriptEnabled = function (value) {
  if (value === void 0) {
    value = savedValue;
  }
  return value('fof-sentry.javascript') !== '0';
};